import { Link, useParams } from 'react-router-dom'

import { Box, Grid, Typography } from '@mui/material'
import { styled } from '@mui/material/styles'

import NotificationBadge from 'src/components/NotificationBadge'
import { useGetMemberRequests } from 'src/hooks/api/memberRequest'
import { PureLightTheme } from 'src/theme/schemes/PureLightTheme'

const TabItem = styled(Grid)(`
    padding: 10px;
    text-align: center;
`)

const TabMenu = () => {
  const params = useParams()
  const clubId = Number(params.id)

  const { data: memberRequests = [] } = useGetMemberRequests(clubId)
  const hasMemberRequests = memberRequests.length > 0

  const menus = [
    { name: '모집 관리', link: `/manage/${clubId}/recruit` },
    { name: '활동 포스팅', link: `/manage/${clubId}/activity` },
    { name: '후기 관리', link: `/manage/${clubId}/review` },
    { name: '회원 명단', link: `/manage/${clubId}/member` },
    { name: '회비 관리', link: `/manage/${clubId}/fee` },
    { name: '행사 관리', link: `/manage/${clubId}/attendance` },
    { name: '동아리 설정', link: `/manage/${clubId}/settings` }
  ]

  return (
    <Box mt={3}>
      <Grid container>
        {menus.map((menu, index) => {
          const isActive = window.location.pathname.startsWith(menu.link)
          const isNotificationBadgeShow = !isActive && menu.name === '회원 명단' && hasMemberRequests

          return (
            <TabItem
              item
              key={index}
              xs={6}
              sm={3}
              md={1.7}
              sx={
                isActive
                  ? { backgroundColor: PureLightTheme.colors.secondary.main, borderRadius: '10px' }
                  : {}
              }
            >
              <Link to={menu.link} style={{ textDecoration: 'none', color: 'black' }}>
                <Box display="flex" alignItems="center" justifyContent="center" gap={0.5}>
                  <Typography variant="h4" sx={isActive ? { color: 'white' } : {}}>
                    {menu.name}
                  </Typography>
                  {isNotificationBadgeShow && (
                    <NotificationBadge count={memberRequests.length} />
                  )}
                </Box>
              </Link>
            </TabItem>
          )
        })}
      </Grid>
    </Box>
  )
}

export default TabMenu
