import { Box, Typography } from '@mui/material'

interface NotificationBadgeProps {
  count: number
}

const NotificationBadge = ({ count }: NotificationBadgeProps) => {
  if (count <= 0) {
    return null
  }

  return (
    <Box
      sx={{
        minWidth: 18,
        height: 18,
        borderRadius: '50%',
        backgroundColor: '#FFA319',
        flexShrink: 0,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        marginLeft: 0.5,
      }}
    >
      <Typography sx={{ color: 'white', fontSize: '0.7rem', fontWeight: 'bold', lineHeight: 1 }}>
        {count}
      </Typography>
    </Box>
  )
}

export default NotificationBadge
